-- Research publications: the database is the source of truth (replacing the
-- external smarthealth.group feed). Reuses public.content_status (0001) and
-- public.media_kind (0003). Safe to re-run.

create table if not exists public.researches (
  id bigint generated by default as identity primary key,
  title text not null,
  authors text,
  abstract text,
  journal text,
  category text not null default 'Publication',
  link text,
  published_date date,
  status public.content_status not null default 'published',
  cover_image_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles(id) on delete set null
);

create table if not exists public.research_media (
  id uuid primary key default gen_random_uuid(),
  research_id bigint not null references public.researches(id) on delete cascade,
  kind public.media_kind not null default 'image',
  storage_path text not null,
  public_url text not null,
  alt_text text,
  caption text,
  sort_order integer not null default 0 check (sort_order >= 0),
  created_at timestamptz not null default now()
);

create index if not exists researches_published_date_idx on public.researches (published_date desc);
create index if not exists research_media_research_idx on public.research_media (research_id, sort_order);

alter table public.researches enable row level security;
alter table public.research_media enable row level security;

drop policy if exists "published researches are readable" on public.researches;
create policy "published researches are readable" on public.researches
  for select using (status = 'published');

drop policy if exists "public research media is readable" on public.research_media;
create policy "public research media is readable" on public.research_media
  for select using (exists (
    select 1 from public.researches where id = research_id and status = 'published'
  ));

-- === Seeded from the live feed (scripts/generate-research-seed.mjs). 29 papers. ===
insert into public.researches (id, title, authors, abstract, journal, category, link, published_date, status, cover_image_url) values
  (1358, 'Warthin-like variant of Papillary Thyroid Carcinoma', 'Dr. Aras Jamal Qadir, Ari Mohammed Abdullah, Dr. Hiwa Omer Ahemd, Dr. Rebaz Omer Mohmmed, Dr. Abdulwahid M. Salih, Dr. Rebaz Haji Ali, Dr. Rawa Muhsin Ali, Shko Hamid Hassan, Dr. Emad Jalal Habibullah Amin, Abdullah Abdueahman Qadir, Harun Amanj Ahmed, Alan Othman Yunis', 'Warthin-like papillary thyroid carcinoma (WL-PTC) is a rare subtype of papillary thyroid carcinoma, defined by oncocytic cells with typical papillary thyroid cancer nuclear features and dense lymphocytic infiltration. Despite its rarity, it usually has a favourable prognosis. A retrospective case series of six patients diagnosed between January 2020 and November 2024 was reviewed, including clinical, imaging, cytology, surgical, histopathological, and follow-up data. The group consisted of five females and one male, with age of patients ranged from 23 to 54 years. Patients presented with thyroid or neck nodules, localised pain, or systemic symptoms. All underwent total thyroidectomy, and three also had lymph node dissections, with two cases showing nodal metastasis. Histopathological examination confirmed WL-PTC, either alone or alongside conventional papillary thyroid carcinoma. No recurrence or residual disease was detected during follow-up, and thyroglobulin levels remained normal. WL-PTC should be accurately identified in pathology reports, and further research is needed to clarify its long-term biological behaviour.', 'Research Connections', 'Case Report', 'https://academic.oup.com/rescon/advance-article/doi/10.1093/rescon/vmag089/8702819?login=false', '2026-06-29', 'published', 'https://smarthealth.group/api/Images/Researches/97fe701a-a490-4694-b12e-b34cc520d3e4.webp'),
  (1355, '‘Umbrella’ technique: An alternative approach to overcoming challenges in breast‑conserving surgery', 'ABDULWAHID M. SALIH, SHABAN L. TOFIQ, HIWA O. BABA, REBAZ O. MOHAMMED, HALKAWT O. ALI, ZUHAIR D. HAMMOOD, AYMAN M. MUSTAFA, LANA R.A. PSHTIWAN, ABDULLAH A. QADIR, SHKO H. HASSAN, VANYA IBRAHIM JWAMER, BUSHRA O. HUSSEIN, HARZAL HIWA FATIH, SHILAN RAOUF QADIR and FAHMI H. KAKAMAD', 'Breast‑oncoplastic surgery can cause deformities, particularly following large excisions or radiotherapy. While oncoplastic techniques enhance patient outcomes, they have limitations in complex cases. The present study aimed to intro‑ duce the ‘umbrella’ technique to overcome these limitations and optimize both oncologic and aesthetic results. The present single‑center retrospective study, conducted from January, 2022 to December, 2023, evaluated the ‘umbrella’ technique for breast cancer treatment. It included patients with early‑stage breast cancer, primarily those who had undergone neoadjuvant chemotherapy. Exclusion criteria included prior breast surgery for unrelated reasons, central tumors and aggressive cancers. Data on demographics, treatments, imaging, tumor characteristics and post‑operative outcomes were collected. Patient satisfaction and follow‑up lasted from 1 month to 2 years, with no documented recurrences. A total of 107 patients participated, with a mean age of 48.49±9.22 years. Of these patients, 95 (88.8%) were <60 years of age, 97 (90.65%) were married and 77 (72%) were non‑smokers. The majority of patients (90, 84.11%) had received chemotherapy. Tumor laterality was almost even, with 54 (50.47%) tumors on the right. Invasive ductal carcinoma was the most common diagnosis (n=61, 57%). The majority of tumors were grade II (n=73, 68.22%). Post‑operative complications included shoulder stiffness (n=27, 25.23%) and infection (n=26, 24.30%). Reoperation was required in 10 (9.35%) patients. All assessed variables had high mean satis‑ faction scores, >8.0. On the whole, the present study demonstrates that the ‘umbrella’ technique improves breast‑conserving surgery by addressing limitations in sensitive tumor areas, providing clear margins, superior cosmetic outcomes and high patient satisfaction, particularly in early‑stage cases. However, the short follow‑up limits oncological conclusions, and long‑term outcomes require further study.', 'Journal website', 'Review', 'https://www.spandidos-publications.com/10.3892/wasj.2026.482', '2026-05-21', 'published', 'https://smarthealth.group/api/Images/Researches/a26ecefe-c92f-4ee3-b95e-11242ea401d0.webp'),
  (1354, 'Thyroid Hemiagenesis with Papillary Thyroid Carcinoma: A Case Report and Literature Review', 'Abdulwahid M. Salih, Ari M. Abdullah, Imad J. Habibullah, Rawa M. Ali, Shko H. Hassan, Mohammed A. HamaAli, Kanaw A. Salih, Shewaz Tariq Latif, Hiwa O. Abdullah, Fahmi H. Kakamad', 'The coexistence of thyroid hemiagenesis (THA) and papillary thyroid carcinoma (PTC) is an exceed-ingly rare condition. This report presents a case of THA with PTC. A 36-year-old woman presented with a one-month history of dyspnea. On examination, the thyroid gland appeared asymmetrical. Neck ultrasound revealed a hypoechoic nodule in the right lobe, classified as Thyroid Imaging Reporting and Data System (TI-RADS) 4. The isthmus and left thyroid lobe were not visualized, suggesting THA. A right thyroid lobectomy was performed, and histopathological examination revealed PTC. Of the 7 reviewed cases of THA with PTC, left lobe agenesis was observed in 4 patients and right lobe agenesis in 3. Fine-needle aspiration cytology was performed in 3 cases, all of which confirmed malignancy. Five cases underwent thyroidectomy, and two underwent lobectomy. The recovery in all cases was satisfactory. Although the coexistence of THA and PTC is extremely rare, the possibility should not be overlooked', 'Journal website', 'Case Report', 'https://www.embj.org/home/article/view/483', '2026-05-19', 'published', 'https://smarthealth.group/api/Images/Researches/d011fb9c-0493-4799-9190-f198028a6580.webp'),
  (1352, 'Pediatric thyroid surgery: a 7-year experience from a high-volume tertiary center', 'Abdulwahid M. Salih, Wrya N. Sabir, Zana B. Najmadden, Bilal A. Mohammed, Karzan M. Hassan, Honar O. Kareem, Shko H. Hassan, Abdullah A. Qadir, Ayman M. Mustafa, Harun A. Ahmed, Fahmi H. Kakamad', 'Pediatric thyroid diseases are associated with higher malignancy and complication rates than in adults. Despite the 2015 American Thyroid Association pediatric guidelines, literature on pediatric thyroid surgery remains limited. This retrospective study aims to present a 7-year, single-center experience in pediatric thyroid surgery. It was conducted from January 2018 to January 2025 and included 60 patients undergoing nodulectomy, lobectomy, or total thyroidectomy for symptomatic thyroid disor- ders or suspicious nodules. The median age was 14 years, with 46 (76.7%) females. The most com- mon complaint was neck swelling observed in 35 individuals (58.3%). Preoperatively, 44 patients (73.3%) had thyroid nodules; 41 (68.3%) had benign disease, while 19 (31.6%) were diagnosed with papillary thyroid carcinoma (PTC). A total thyroidectomy was the most common procedure performed in 26 cases (43.3%). A significant correlation was found between surgery duration and hospitalization (r=0.528, p<0.001). Pediatric thyroid surgery is generally safe, with total thyroidectomy being the most frequently performed procedure. Given the relatively high malignancy rate and surgical complexity, optimal outcomes depend on multidisciplinary care and surgeon expertise in pediatric thyroid pathology.', 'Journal website', 'Case Report', 'https://www.embj.org/home/article/view/482', '2026-05-10', 'published', 'https://smarthealth.group/api/Images/Researches/21b70511-d3ff-47cf-86b3-0e3fe68e2066.webp'),
  (1348, 'Aberrant metastasis of invasive pleomorphic lobular carcinoma: A case report and brief review of the literature', 'Hadeel Adnan Yasseen, Ari M. Abdullah, Rebaz M. Ali, Lana R.A. Pshtiwan, Karzan M. Salih, Abdulwahid M. Salih, Sakar O. Arif, Shko H. Hassan, Harzal H. Fatih, Masty K. Ahmed, Abdullah A. Qadir, Fahmi H. Kakamad', 'Pleomorphic lobular carcinoma (PLC) is a rare type of invasive lobular carcinoma. It is more aggressive and is associated with a poorer prognosis, and distinct cytologic characteristics. The present study reports a rare case of invasive PLC metastasis to the peritoneum and ovaries, and also performs a brief review of the literature. A 51‑year‑old woman with a family history of breast cancer presented with multiple right breast masses and right axillary lymphadenopathy. Imaging and biopsy confirmed invasive PLC, which was estrogen receptor (ER)/progesterone receptor (PR)‑positive and human epidermal growth factor receptor 2 (HER2)‑negative, with metastatic involvement of the axillary lymph nodes. Laparoscopy and immunohistochemistry revealed bilateral ovarian and peritoneal metastases. The patient was diagnosed with metastatic PLC of breast origin. A multidisciplinary team initiated systemic therapy with palbociclib, letrozole and Zoladex. She is currently on her fifth treatment cycle, with stable disease and no reported complications. Ongoing follow‑up continues to monitor her progress. From the literature, a total of 6 cases of breast cancer metastasis to the ovaries and 1 case involving the peritoneum were reviewed. Computed tomography was the most commonly used imaging modality, with diagnostic confirmation achieved through histopathological examination. Surgeries were performed, 1 patient succumbed, and 1 patient was lost to follow‑up. Immunohistochemistry is critical for differentiating primary and metastatic ovarian tumors. These markers include GATA3, ER, PR, HER2, Ki‑67, GCDFP‑15, CK7 and the lack of E‑cadherin. The same differentiation is crucial for metastasis to the peritoneum. On the whole, the present case report demonstrates that breast carcinoma metastases to the ovaries and peritoneum are rare, yet essential to consider. Immunohistochemistry helps differentiate them from other carcinomas.', 'Journal website', 'Case Report', 'https://www.spandidos-publications.com/10.3892/wasj.2026.446', '2026-02-24', 'published', 'https://smarthealth.group/api/Images/Researches/21e86064-c0de-45fd-a819-73215b1dcc70.webp'),
  (1330, 'Desmoid‑type fibromatosis of the head and neck region: A case report and brief review of the literature', 'Wrya N. Sabir, Abdulwahid M. Salih, Ari M. Abdullah, Hiwa O. Baba, Abdullah A. Qadir, Hardi M. Dhahir, Rebaz O. Mohammed, Aso S. Muhialdeen, Shko H. Hassan, Karzan M. Salih, Fahmi H. Kakamad', 'Desmoid‑type fibromatosis (DTF) is a rare tumor characterized by locally infiltrating mesenchymal growth. Its occurrence in the head and neck region is rare. The present study describes the case of a male pediatric patient diagnosed with DTF involving the level II. A 2‑year‑old male patient presented with a progressively enlarging left submandibular mass over a period of 3 months. The results of hematological tests were normal. A neck ultrasound revealed a well‑defined, lobulated hypoechoic left subcutaneous mass, measuring 38x31x27 mm, with mild vascularity and features suggestive of a suppurative or necrotic lymph node, accompanied by bilateral cervical lymphadenopathy with preserved morphology, with the largest node measuring 15x6 mm in the left level II. Computed tomography scan revealed no chest or abdominal abnormalities. The mass was completely excised, and a histopathological analysis confirmed DTF. The patient was discharged in good health. In addition, following a literature search, seven reported cases of DTF in the head and neck region were reviewed; the patients were aged 9 months to 42 years. DTF was found in the neck in 4 cases, in the mandible in 2 cases, and tongue in 1 case. Surgical excision led to uneventful outcomes for the majority of patients. DTF of the head and neck presents a complex clinical scenario. Its rarity and the challenges associated with diagnosis, location and treatment necessitate careful consideration, particularly in pediatric cases, in order to prevent unnecessary intervention and complications.', 'Journal website', 'Case Report', 'https://www.spandidos-publications.com/10.3892/wasj.2026.430', '2026-01-20', 'published', 'https://smarthealth.group/api/Images/Researches/8bc4a30c-6192-4830-8445-7d887921aae0.webp'),
  (1329, 'Primary breast lymphoma: Case report and literature review', 'Lana R.A. Pshtiwan, Ari M. Abdullah, Abdulwahid M. Salih, Dana O. Karim, Karzan M. Salih, Bayar B. Ameen, Sakar O. Arif, Masty Karim Ahmed, Sara Nasir Ahmed, Ali D. Saadullah, Fahmi H. Kakamad.', 'Primary breast lymphoma (PBL) accounts for a small fraction of breast malignancies and is uncommon in young adults, yet it can lead to significant complications. This report describes a case of PBL in a young female patient. An 18-year-old female presented with a mass in the right breast with fever and sweating. Examination revealed a poorly defined right breast mass. Imaging showed a diffuse infiltrative process, and core biopsy with staining identified the lymphoid origin of the infiltrative disease. Chemotherapy was opted for, and follow-up for months has revealed no complications. Ten cases were reviewed. The mean age was (19.7). The most common symptom was a palpable breast mass(s) (60%). Imaging showed variable signal intensities of the breast masses. Immunohistochemistry and flow cytometry of tissue biopsies were the main methods of diagnosis. Large B-cell non-Hodgkin lymphoma was the most common diagnosis (60%). Chemotherapy was utilized in all of the cases with variations regarding regimens. Death and remission were seen in near equal proportions (40% vs 50%). Young women are not exempt from primary breast lymphoma, and chemotherapy might offer fruitful outcomes.', 'Journal website', 'Case Report', 'https://www.sciencedirect.com/science/article/pii/S1930043325011501', '2026-01-17', 'published', 'https://smarthealth.group/api/Images/Researches/eb538ae6-5e62-4197-aba9-c43eaef4951e.webp'),
  (1341, 'Exploring the Efficacy of Once and Twice Weekly Thyroxine Dosing: A Promising Approach for Hypothyroidism Management', 'Abdulwahid M. Salih, Aso S. Muhialdeen, Mohsin M. Ahmed, Hardi M. Zahir, Yadgar A. Saeed, Saeed H. Ali, Hiwa O. Baba, Shaho F. Ahmed, Muhammed Bag A. Ali, Hunar A. Hassan, Shko H. Hassan, Marwan N Hassan, Swara H. Abdullah', 'Introduction Hypothyroidism is a common endocrine disorder, in which the management involves daily intake of thyroxine. However, adherence to a daily medication regimen poses a substantial challenge for many patients. The current study aims to assess the efficacy of once and twice-weekly thyroxine regimen for the management of hypothyroidism. Methods This was a single-center cohort study involving hypothyroid patients that was conducted over three years. In this study, standard daily, once and twice-weekly thyroxine dosing regimens were used to treat the patients. The effectiveness of the three dosage regimens was ascertained by whether the patients achieved a euthyroid state after six months of therapy. Results In total, 328 hypothyroid cases due to thyroiditis were included in this study. The average age of the cases was 42.7 years (14-92). Before thyroxine therapy, in the standard daily regimen group, the median level of TSH was 15.4 μIU/mL (IQR 23.1), in the once-weekly regimen group, the level was 9.2 μIU/mL (IQR 6.8), and in the twice-weekly regimen group, the level was 9.1 μIU/mL (IQR 7.3). After thyroxine intake and upon follow-up after 6 months, the TSH level decreased to 4.0 μIU/mL (IQR 3.7), 4.5 μIU/mL (IQR 4.9) and 4.2 μIU/mL (IQR 5.1) in the standard daily, once- and twice-weekly regimen groups, respectively. Conclusion Once and twice weekly thyroxine shows promise as strategies for managing hypothyroidism. However, variability in patients in response to weekly thyroxine needs to be taken into account.', 'Journal website', 'Paper', 'https://www.barwmedical.com/index.php/BMJ/article/view/211', '2025-11-18', 'published', 'https://smarthealth.group/api/Images/Researches/6178f684-239f-4f86-a656-9a389eea7620.webp'),
  (1333, 'Unusual Metastasis from Follicular Thyroid Carcinoma: A Case Report and Literature Review', 'Abdulwahid M. Salih, Deari A. Ismaeil, Rawa M. Ali, Ari M. Abdullah, Karzan M. Salih, Shko H. Hassan, Twana Omer Saeed, Ahmed H. Ahmed, Harun Amanj Ahmed', 'Introduction Follicular thyroid carcinoma (FTC) is a type of well-differentiated thyroid carcinoma. It has a poorer prognosis, is more metastatic, and has characteristics different from papillary thyroid carcinoma. It tends to metastasize hematogenously, usually to the bones and lungs. This study aims to present a rare case of FTC metastasis to the peritoneum and thigh of a patient with a literature review. Case presentation A 70-year-old patient presented with a right thigh mass. Magnetic resonance imaging of the right thigh revealed an intramedullary lesion in the femoral diaphysis. The thyroid gland was firm, with no evidence of enlargement. A computed tomography scan showed several peritoneal nodules. A core biopsy of the right upper femoral lesion and peritoneal mass was performed. Histopathologic findings and immunohistochemical analysis confirmed metastatic FTC with thyroid origin. Literature review Unlike widely invasive FTC, minimally invasive FTC has a better prognosis and is less metastatic. Imaging, histopathologic examination, and immunohistochemistry can help in arriving at a diagnosis of FTC. Mutations of PPAR-γ and RAS are associated with FTC. Radioiodine treatment and suppressive therapy for the thyroid-stimulating hormone have been shown to improve survival rates of FTC, with postoperative follow-ups and treatment being important. Conclusion Metastasis of FTC to the peritoneum is rare and could lead to a late diagnosis. Proper diagnosis with confirmatory tools such as immunohistochemistry and adequate treatment are critical.', 'Journal website', 'Case Report', 'https://www.barwmedical.com/index.php/BMJ/article/view/218', '2025-12-20', 'published', 'https://smarthealth.group/api/Images/Researches/1de680b0-40eb-439e-b9dd-a7f29e76e84b.webp'),
  (1327, 'Papillary thyroid carcinoma with squamous differentiation: A report of two cases and a brief review of the literature', 'Ari M. Abdullah, Rawa M. Ali, Abdulwahid M. Salih, Imad J. Habibullah, Hadeel A. Yasseen, Twana Omer Saeed, Shko H. Hassan, Harun Amanj Ahmed, Abdullah A. Qadir, Fahmi H. Kakamad', 'Papillary thyroid carcinoma (PTC) is the most common type of thyroid cancer with a good prognosis. However, in rare cases, it can behave aggressively and exhibit unusual features such as squamous differentiation, where squamous cells appear alongside typical PTC cells. PTC with squamous differentiation (PTC‑SD) is extremely rare and is thus not well understood. The present study reports two cases of PTC‑SD. The first case was that of a 28‑year‑old female patient who presented with a neck mass and hoarseness, and another that of a 49‑year‑old male patient who presented with an incidental finding of a thyroid lesion during a neck ultrasound for a dental issue. Upon investigations, both patients had suspicious thyroid nodules. A total thyroidectomy was performed for both cases. A histopathological examination confirmed PTC‑SD. Levothyroxine was prescribed for both patients, and radioactive iodine ablation was scheduled for the first case. Squamous epithelium in the thyroid is rare and can result from various causes, including primary thyroid squamous cell carcinoma, anaplastic transformation, metastasis, or PTC‑SD. Although the available data are limited, they indicate that PTC‑SD may be associated with a poorer prognosis compared to conventional PTC. Herein, in a review of 4 cases reported in the literature, it was found that 1 patient succumbed and another experienced recurrence. Despite its rarity, recognizing this variant is crucial for an accurate diagnosis and appropriate treatment planning. Patients with PTC‑SD require careful monitoring, with the majority undergoing surgical resection. Though rare, clinicians should recognize that PTC can undergo squamous differentiation.', 'Journal website', 'Case Report', 'https://www.spandidos-publications.com/10.3892/wasj.2025.423', '2025-12-31', 'published', 'https://smarthealth.group/api/Images/Researches/67b7f1f0-bfc5-4543-b1fe-a2e73dbe777c-454x1024.png'),
  (1325, 'Psammoma bodies in a benign thyroid gland: A case report and brief review of the literature', 'Ari M. Abdullah, Hadeel A. Yasseen, Rawa M. Ali, Shaho F. Ahmed, Abdulwahid M. Salih, Imad J. Habibullah, Twana Omer Saeed, Shko H. Hassan, Harun Amanj Ahmed, Fahmi H. Kakamad', 'Psammoma bodies (PBs) are round, layered calcified structures usually associated with papillary thyroid cancer and may be observed in 40‑50% of cases, but may rarely occur in benign thyroid disease. The present study describes a rare case of PBs being found in a benign thyroid gland. In addition, a brief review of the literature is presented. A 28‑year‑old female patient presented with a 3‑month history of weight loss, poor appetite and generalized weakness. Her thyroid was firm and mildly enlarged. Thyroid function was within normal limits (thyroid‑stimulating hormone, 0.85 µIU/ml; free T4, 20.1 pmol/l; thyroglobulin, 6.15 ng/ml). An ultrasound demonstrated bilateral TI‑RADS‑3 nodules measuring 25x21x19 mm (right) and 17x15x13 mm (left). A total thyroidectomy revealed thyroid follicular nodular disease with focal lymphocytic thyroiditis and PBs, but no malignancy. In the literature, 4 cases of PBs or psammomatous calcifications linked to benign conditions were identified, 2 males and 2 females. Half of the cases involved the thyroid‑region lesions and half were pediatric (2/4). All cases underwent surgical excision, and fine‑needle aspiration was diagnostic in only 1 case (25%). A computed tomography scan was used in 2 cases (50%). A histological analysis confirmed PBs or psammomatous calcifications in every case, and all patients had favorable outcomes with no recurrence upon follow‑up. When PBs are detected without tumor cells, submitting the entire thyroid tissue for histology is recommended to rule out microscopic carcinoma. PBs can arise in benign thyroid follicular nodular disease, mimicking malignancy on imaging and cytology, accurate diagnosis requires comprehensive histopathological evaluation.', 'Journal website', 'Case Report', 'https://www.spandidos-publications.com/10.3892/mi.2025.282', '2025-10-29', 'published', 'https://smarthealth.group/api/Images/Researches/58277fcb-42cc-4c04-93f1-ea965e18b929-419x1080.png'),
  (1323, 'Percutaneous ablation of intrathyroidal parathyroid adenoma: A case report and brief review of the literature', 'Aras J. Qaradakhy, Abdulwahid M. Salih, Shaho F. Ahmed, Rebaz M. Ali, Ari M. Abdullah, Aso N. Qadir, Imad J. Habibullah, Hawkar A. Nasralla, Abdullah A. Qadir, Fahmi H. Kakamad', 'Primary hyperparathyroidism (HPT), predominantly caused by parathyroid adenomas (PAs), leads to elevated calcium levels and a range of complications, including renal, skeletal and cardiovascular issues. While parathyroidectomy is the standard treatment for resolving hypercalcemia, the present study describes a case of intrathyroidal PA treated with microwave ablation (MWA). A 29‑year‑old woman with recurrent HPT presented with elevated parathyroid hormone (183 pg/ml) and serum calcium (11.06 mg/dl) levels following a previous right upper and lower parathyroidectomy. Imaging revealed a well‑defined hypoechoic nodule within the right thyroid lobe, confirmed as an intrathyroidal PA following sestamibi scanning. The patient underwent MWA, achieving the rapid normalization of parathyroid hormone and calcium levels. Although PA is a common cause of primary HPT, a thorough review of the literature found no instances of intrathyroidal PA treated with MWA. On the whole, the present case report demonstrates that MWA may be a safe and effective alternative for the treatment of intrathyroidal PAs, particularly when traditional surgery is not a viable option.', 'Journal website', 'Case Report', 'https://www.spandidos-publications.com/10.3892/mi.2025.285', '2025-11-11', 'published', 'https://smarthealth.group/api/Images/Researches/6de88f71-c150-4d31-b6ab-2b0bacd06a52-425x839.png'),
  (1319, 'Preoperative Thyroglobulin and Thyroid Pathologies: A Single Center Experience', 'Shaho F. Ahmed, Rebaz M. Ali, Rawa M. Ali, Ari M. Abdullah, Abdulwahid M. Salih, Hiwa O. Baba, Rebaz O. Mohammed, Aso N. Qadir, Shko H. Hassan, Abdullah A. Qadir, Harun A. Ahmed, Hawkar A. Nasralla, Berun A. Abdalla, Fahmi H. Kakamad', 'Introduction: Thyroid nodules are frequently found in the general population, though malignancy is confirmed in only a minority of cases. Distinguishing between benign and malignant nodules before surgery is vital for appropriate clinical management. The utility of preoperative serum thyroglobulin (Tg) levels as a diagnostic marker in thyroid carcinomas remains controversial. This study aimed to provide a descriptive overview of patients with markedly elevated preoperative Tg levels (>500 ng/mL) and their corresponding histopathological outcomes. Methods: A retrospective, single-center study was conducted at Smart Health Tower, which included patients who underwent surgical interventions for thyroid disorders between 2019 and 2025, with preoperative serum Tg levels exceeding 500 ng/mL. Patients were excluded if they had incomplete medical records. Patient demographics, clinical features, preoperative findings, surgical details, and final histopathology were retrieved from electronic medical records. Results: A total of 260 patients were included, predominantly female (73.08%), with a median age of 49 years (QR: 38–61). Neck swelling was the most common symptom (63.08%). Ultrasonography showed follicular nodular disease in 60.0%. Fine-needle aspiration cytology revealed Bethesda II in 20.0%, IV in 13.85%, and VI in 11.15% of cases. Total thyroidectomy was performed in 74.62% of cases. Histopathology showed benign lesions in 70.77% and malignant lesions in 29.23% of the cases. Conclusion: Preoperative Tg levels may be elevated in both benign and malignant thyroid disorders; however, Tg may not possess adequate diagnostic precision to be used as a sole indicator of malignancy.', 'Journal website', 'Paper', 'https://www.judijournal.com/index.php/jd/article/view/32', '2025-11-12', 'published', 'https://smarthealth.group/api/Images/Researches/13072342-7932-44cc-b04e-f04bfcdc1a05-608x1080.jpg'),
  (1318, 'Male Breast Cancer: A Single Center Case Series', 'Abdulwahid M. Salih, Lana RA. Pshtiwan, Fattah H. Fattah, Ari M. Abdullah, Rebaz M. Ali, Rebaz O. Mohammed, Hiwa O. Baba, Ahmed H. Ahmed, Sakar O. Arif, Nasren S. Sabr, Shko H. Hassan, Harzal H. Fatih, Masty K. Ahmed, Meer M. Abdulkarim, Hiwa O. Abdullah, Fahmi H. Kakamad', 'Introduction: Male breast cancer is a rare malignancy, and despite increasing its prevalence, little is known about its prognosis, and management continues to rely largely on guidelines developed for female breast cancer. This study presents a single-center experience focusing on the diagnosis, therapeutic strategies, and prognostic outcomes associated with male breast cancer. Methods : The study was carried out between May 2020 and January 2025. All the male patients diagnosed with breast cancer were identified from the center''s database. The study included those with complete medical records, encompassing demographics, clinical presentation, imaging findings, outcome, and follow-up data. Results : Fifteen male breast cancer cases were analyzed (mean age 59.47 ± 12.97 years). The left breast was affected in 60%, and 80% presented with a painless lump. Tumor size ranged 0.6–5.4 cm (mean 2.53 ± 1.50 cm). Modified radical mastectomy was performed in 86.66%. Invasive ductal carcinoma predominated (93.33%), with lymph node involvement in 40% and bone metastasis in 6.67%. Immunohistochemistry results were available for 5 patients (33.33%); all of them were estrogen receptor and progesterone receptor positive and human epidermal growth factor receptor 2 negative. Adjuvant chemotherapy and radiotherapy were used in 33.33%, while 20% received triple modality therapy. Mean follow-up was 2.8 ± 1.52 years (range 1–5), with one recurrence. Conclusion : Male breast cancer may present as a breast mass and is often diagnosed as invasive ductal carcinoma. Modified radical mastectomy accompanied by adjuvant therapy might offer favorable outcomes.', 'Journal website', 'Paper', 'https://www.judijournal.com/index.php/jd/article/view/30', '2025-11-15', 'published', 'https://smarthealth.group/api/Images/Researches/f0240c39-f673-4757-975f-5edba53f5ecf-411x1080.jpg'),
  (1315, 'Accessory breast granulomatous mastitis: A case report and mini‑review of the literature', 'Abdulwahid M. Salih, Ari M. Abdullah, Lana R.A. Pshtiwan, Sakar O. Arif, Zuhair D. Hammood, Shaban L. Tofiq, Hiwa O. Abdullah, Masty K. Ahmed, Harzal Hiwa Fatih, Meer M. Abdulkarim, Fahmi H. Kakamad', 'Granulomatous mastitis (GM) is a rare inflammatory condition that primarily affects the breasts, and its occurrence in accessory breast tissue is even rarer. The present report describes the case of a patient with GM in the accessory breast. A 43‑year‑old female patient presented with a 1‑month history of pain in the left axilla and breast. An analysis of her medical and surgical history did not reveal any notable findings, but she had a history of four full‑term pregnancies and a cumulative lactation period of 4 years. Upon a clinical examination, a palpable, ill‑defined, tender mass was noted along with an accessory breast and nipple in the axilla. The diagnosis was chronic mastitis, and she was treated with oral corticosteroids, amoxicillin, cabergoline and analgesics. Her condition initially improved; however, the symptoms recurred 1 year later. A wide local excision of the left axillary tail was performed. The patient experienced marked improvement post‑surgery and remained stable, with no recurrence, at the 1‑year follow‑up. In addition, in the present study, seven recent cases of GM were included for a brief literature review, involving patients aged 23 to 42 years. Of these cases, 6 cases did not have any notable medical histories. A total of 6 patients had a history of pregnancy, with an average lactation duration of 22.7 months. The right breast was affected in 6 cases. Pain and swelling were the most frequent symptoms. A conservative approach, which included antibiotics, corticosteroids and wound dressing was used for 5 patients. In total, 6 patients achieved recovery. On the whole, the present study demonstrates that accessory breast tissue can develop GM. While corticosteroids may provide favorable short‑term results, they do not necessarily prevent recurrence, whereas surgical management may provide more durable long‑term outcomes.', 'Journal website', 'Case Report', 'https://www.spandidos-publications.com/10.3892/mi.2025.277', '2025-10-23', 'published', 'https://smarthealth.group/api/Images/Researches/02cf21bd-3b72-45bd-9062-a564961f8fcd-495x896.png'),
  (1301, 'Papillary thyroid cancer in prepubertal patients: A report of two cases and a brief review of the literature', 'Abdulwahid M. Salih, Aras J. Qaradakhy, Ari M. Abdullah, Karzan M. Salih, Shaho F.  Ahmed, Zana B. Najmadden, Meer M. Abdulkarim, Harun Amanj Ahmed, Shko H. Hassan, Abdullah A. Qadir, Aso N. Qadir, Fahmi H. Kakamad', 'Although papillary thyroid carcinoma (PTC) is relatively rare in children, particularly in the prepubertal age group, its biological behavior resembles that of other pediatric solid tumors, where delayed diagnosis can significantly affect outcomes. In the broader oncology context, rare pediatric malignancies, such as prepubertal PTC, highlight the importance of tailoring diagnostic and therapeutic strategies to those applied in adults. PTC in prepubertal children is a rare occurrence that presents with a high likelihood of distant metastasis. The present study describes 2 cases of PTC in 9‑year‑old girls with irrelevant medical, surgical, or family history. The first case was that of a 9‑year‑old girl with a painless neck swelling for 4 weeks. An ultrasonography revealed diffuse thyroid lesions and cervical lymphadenopathy. She underwent a total thyroidectomy with bilateral neck dissection. Pathological analysis confirmed diffuse sclerosing PTC with numerous positive lymph nodes. She recovered well and received radioactive iodine therapy. The second case was that of a 9‑year‑old girl with right‑sided neck swelling for 1 year. Imaging revealed a Thyroid Imaging Reporting and Data System 5 nodule and suspicious lymph nodes. She underwent a total thyroidectomy with bilateral central and right lateral neck dissection. Pathological analysis confirmed unifocal conventional PTC with 17 positive lymph nodes. She recovered well, received radioactive iodine therapy, and remained recurrence‑free for 3 years. In addition, in the present study, a literature search was performed on the PubMed and Google Scholar database, covering the period from January, 2017 to February, 2025. The search used combinations of the following key words: ‘papillary thyroid carcinoma’, ‘papillary thyroid cancer’, ‘thyroid neoplasm’, ‘pediatric’ and ‘prepubertal’. Only articles published in the English language and reporting individual prepubertal PTC cases were considered. From this search, 9 relevant cases were identified and were included in a brief review of the literature, of which 5 cases were females. The ages of the patients ranged from 5 to 17 years. The right thyroid lobe was involved in 4 patients, and bilateral involvement was reported in 1 case. Tumors were multifocal in 7 patients, and lymph nodes were involved in 8 patients. A total of 7 cases were of conventional variation, and distant metastases were reported in 4 cases, all of which were in the lungs. Total thyroidectomy was performed for all the cases. As demonstrated herein, papillary thyroid carcinoma in prepubertal children is uncommon. Total thyroidectomy may provide good long‑term outcomes.', 'Journal website', 'Paper', 'https://www.spandidos-publications.com/10.3892/mi.2025.273', '2025-10-01', 'published', 'https://smarthealth.group/api/Images/Researches/6780e520-d63b-408c-ae46-085303cc6773-542x1080.png'),
  (1300, 'Granulomatous mastitis with erythema nodosum: A case report and mini‑review of the literature', 'Ronak Saeed Ahmed, Abdulwahid M. Salih, Lana R.A. Pshtiwan, Aso S. Muhialdeen, Karzan M. Salih, Masty K. Ahmed, Hardi M. Dhahir, Shko H. Hussein, Halkawt Omer Ali, Fahmi H. Kakamad', 'Granulomatous mastitis (GM) is a rare chronic inflammatory disease of the breast, often mistaken for malignancy. The present study describes the case of a patient with GM associated with erythema nodosum (EN). A 37‑year‑old female patient presented with a 2‑month history of a painful mass in the left breast, accompanied by bilateral skin lesions on the lower limbs. A physical examination revealed a tender breast mass (3 cm in size) and multiple erythematous subcutaneous nodules on the lower limbs. Laboratory tests revealed an elevated white blood cell count and hypochromic microcytic anemia. A breast ultrasonography demonstrated a hypoechoic mass in the left breast. Core needle biopsy revealed non‑caseating granulomas consistent with GM. The final diagnosis was GM associated with EN. Treatment with prednisolone and colchicine led to the resolution of symptoms within 4 weeks. In addition, a brief literature review identified six studies reporting cases of GM with EN, all of which occurred in female patients aged 16 to 42 years. Of note, three cases had lesions in the right breast. Common presentations included breast pain, swelling and EN with systemic symptoms such as arthralgia. Histopathological analyses consistently showed granulomatous inflammation with negative cultures. Treatment primarily involved the use of corticosteroids, resulting in significant improvement or resolution. In general, an accurate diagnosis of GM is crucial to prevent unnecessary interventions. Management with corticosteroids can lead to favorable outcomes. Understanding systemic associations, such as EN, is vital for comprehensive patient care.', 'Journal website', 'Paper', 'https://www.spandidos-publications.com/10.3892/wasj.2025.402', '2025-09-26', 'published', 'https://smarthealth.group/api/Images/Researches/e7d015a2-3c04-44a1-bc1b-66d3e2bcc2b3-500x1080.png'),
  (1299, 'Primary hydatid cyst of the breast: A case report and mini‑review of the literature', 'Lana R.A. Pshtiwan, Abdulwahid M. Salih, Hiwa O. Abdullah, Halkawt Omer Ali, Khanda A. Anwar, Ari M. Abdullah, Shko H. Hassan, Sasan M. Ahmed, Fattah H. Fattah, Rawa M. Ali, Shaban Latif, Bushra O. Hussein', 'Hydatid disease is a zoonotic infection with a diverse range of clinical presentations. Breast involvement is an extremely rare occurrence. The present study describes the case of an elderly female patient who presented with a longstanding breast hydatid cyst (HC) masquerading as a painless mass. A 79‑year‑old female patient presented with a slowly enlarging lump in her left breast for the past 20 years. A mammography revealed a circumscribed, hyperdense mass. The lump was surgically excised. A histopathological examination revealed benign breast ducts and lobules in a fibrous stroma containing a well‑defined cyst composed of lamellated, chitinous layers of a HC. In addition, a review of 11 cases of breast HC in females identified in the literature revealed that the disease frequently presented as a painless, slowly growing breast mass. The disease duration prior to presentation ranged from 2 to 36 months. The cysts were located in the left breast in 8 cases, in the right breast in 2 cases, and there was bilateral involvement in 1 case. The majority of these cysts were localized to the upper outer quadrant. On the whole, as demonstrated herein, breast HC can remain asymptomatic for a long period of time and may masquerade as a gradually enlarging, painless breast mass.', 'Journal website', 'Paper', 'https://www.spandidos-publications.com/10.3892/wasj.2025.400', '2025-09-25', 'published', 'https://smarthealth.group/api/Images/Researches/422e7c7f-79c1-4fb8-8e51-642226bfb426-575x1080.png'),
  (1296, 'Water‑clear cell parathyroid adenoma: A case report and mini‑review of the literature', 'Ari M. Abdullah, Aras J. Qaradakhy, Rebaz M. Ali, Abdulwahid M. Salih, Hiwa O. Baba, Rebaz O. Mohammed, Abdullah A. Qadir, Hawkar A. Nasralla, Shko H. Hassan, Fahmi H. Kakamad', 'Water‑clear cell parathyroid adenoma (WCCPA) is a rare variant of parathyroid adenoma, characterized by large polygonal cells with optically clear cytoplasm. To date, only a limited number of cases have been reported in the English literature. The present study describes the case of a patient with WCCPA. An 80‑year‑old female presented with muscle pain and fatigue lasting for 1 week. A clinical examination revealed a normal thyroid gland with no palpable masses. Laboratory tests revealed elevated levels of serum calcium (12.73 mg/dl) and parathyroid hormone (PTH; 303 pg/ml). A neck ultrasonography revealed a 28x16x11 mm hypoechoic, mildly vascular lesion, suspicious of a parathyroid nodule, located posterior to the left thyroid lobe. A left lower parathyroidectomy was performed, and a histopathological examination confirmed the diagnosis of WCCPA. Post‑operatively, the serum calcium and PTH levels of the patient normalized, and her recovery was uneventful. In addition, a review of 4 recent cases of WCCPA found in the literature demonstrated a common clinical pattern of elevated calcium levels and increased PTH levels. Imaging techniques, such as ultrasonography and sestamibi scans revealed localized parathyroid lesions, which were subsequently confirmed as WCCPA through histopathological evaluation. Surgical excision was performed in all cases, resulting in postoperative normalization of calcium levels in the majority of patients. WCCPA is a rare, yet significant cause of primary hyperparathyroidism. An accurate diagnosis relies on a histopathological examination, as clinical and imaging findings may be non‑specific. Surgery can yield favorable outcomes.', 'Journal website', 'Paper', 'https://www.spandidos-publications.com/10.3892/mi.2025.269', '2025-09-17', 'published', 'https://smarthealth.group/api/Images/Researches/9cc45852-ed73-4419-92c6-c2dfe9d0cb91-597x1033.png'),
  (1293, 'Granulomatous mastitis co‑existing with breast cancer: A case report and mini‑review of the literature', 'Abdulwahid M. Salih, Shaban Latif, Rebaz M. Ali, Lana R.A. Pshtiwan, Halkawt Omer Ali, Ari M. Abdullah, Karzan M. Salih, Shko H. Hassan, Hawkar A. Nasralla, Bushra O. Hussein, Fahmi H. Kakamad', 'Granulomatous mastitis (GM) is a rare inflammation of the breast marked by non‑caseating granulomatous lesions near the breast ducts and lobules. Reports of GM coinciding with breast cancer are rare. The present study describes the case of a patient with GM, high‑grade high‑grade ductal carcinoma in situ (DCIS), and invasive ductal carcinoma were present in the same breast. A 36‑year‑old woman with a 2‑week history of left breast pain was found to have a large, firm lump. A core needle biopsy led to the diagnosis of DCIS and suppurative GM. The patient was initially treated with analgesics and antibiotics for 20 days. Eventually, the patient underwent a complete mastectomy with immediate reconstruction using a TRAM flap. A subsequent histopathological examination revealed invasive ductal carcinoma of no specific type, poorly differentiated, with extensive DCIS and suppurative GM. Upon the last follow‑up, the patient was monitored and remained stable with no post‑operative complications. Furthermore, in a literature review conducted utilizing Google Scholar and PubMed, only 13 cases of the simultaneous presence of GM and breast cancer were found. The average age of these patients was 43.07±12.10 years. Of note, 7 (53.85%) of these patients had both GM and breast cancer in the left breast, while only 2 cases (15.38%) involved the conditions in contralateral breasts. In conclusion, distinguishing between breast cancer and GM is challenging. Although the simultaneous presence of GM and breast cancer is rare, it remains essential to consider this possibility. However, further research is required to clarify the association between GM and breast cancer.', 'Journal website', 'Paper', 'https://www.spandidos-publications.com/10.3892/wasj.2025.389', '2025-09-04', 'published', 'https://smarthealth.group/api/Images/Researches/2d49c280-5b11-4e77-a6ae-406315d33838-337x617.png'),
  (1292, 'Carcinoma ex Pleomorphic Adenoma: A Case Series and Literature Review', 'Abdulwahid M. Salih, Rebaz M. Ali, Ari M. Abdullah, Aras J. Qaradakhy, Ahmed H. Ahmed, Imad J. Habibullah, Sarwat T. San Ahmed, Mariwan L. Fatah, Abdullah A. Qadir, Meer M. Abdulkareem, Shko H. Hassan, Harun Amanj Ahmed', 'Introduction: Carcinoma ex pleomorphic adenoma (CXPA) is a rare malignant salivary gland tumor that can lead to severe complications and carries a risk of distant metastasis. This study aims to provide a comprehensive overview of CXPA through a case series and a review of the literature. Methods: This was a single-center retrospective case series. The patients were included from November 2018 to December 2024. All confirmed cases of CXPA that were diagnosed and managed with complete clinical data were included in this study. Cases with incomplete data were excluded. Results: Six patients were included, with ages ranging from 45 to 88 years (mean ± SD: 64 ± 15.36; median: 62). Most were male (66.7%), with an even distribution of occupations. All presented with preauricular swelling lasting 2 to 10 years, and three had left-sided tumors. Fine needle aspiration identified 33.3% as benign and 16.7% as malignant. Ultrasound examination showed solid tumors in four cases, three of which were well-defined. Three (50%) underwent total parotidectomy, and three (50%) underwent superficial parotidectomy. Histopathological examination revealed adenocarcinoma ex pleomorphic adenoma in 50% and squamous cell carcinoma ex pleomorphic adenoma in 16.7%. Tumor sizes ranged from 3.5 to 6 cm (mean: 4.73 ± 1.24 cm). Capsular invasion was present in all cases, with lymph node involvement in 33.3%, lympho-vascular invasion in 16.7%, and perineural invasion in 50%. Adjuvant therapy included radiotherapy or chemoradiotherapy. Conclusion: Although CXPA is very rare, it is a serious condition; surgical approach with or without adjuvant therapy may result in preferable outcomes.', 'Journal website', 'Paper', 'https://www.barwmedical.com/index.php/BMJ/article/view/202', '2025-08-28', 'published', 'https://smarthealth.group/api/Images/Researches/ea7f4476-814a-4161-bf3e-c98a20fdeb2b-587x1080.png'),
  (1291, 'Primary breast osteosarcoma: A case report and mini‑review of the literature', 'Ari M. Abdullah, Abdulwahid M. Salih, Lana R.A. Pshtiwan, Soran H. Tahir, Shaban Latif, Rebaz M. Ali, Rawa M. Ali, Hiwa O. Abdullah, Meer M. Abdulkareem, Vanya I. Jwamer, Abdullah A. Qadir, Fahmi H. Kakamad', 'Primary breast osteosarcoma (PBO) is an exceedingly rare form of breast cancer. The present study reports the case of a 45‑year‑old female patient with PBO with atypical manifestations. The patient sought medical consultation due to a painful, slowly growing lump in her left breast for 2 months. Upon a physical examination, a palpable mass was noted in the left upper outer quadrant. The mass was ill‑defined, hard, tender and immobile. There was no axillary lymphadenopathy. A core needle biopsy from the mass indicated a breast fibroadenoma with focal inflammation and a giant cell reaction, while the axillary lymph nodes were benign. The patient underwent wide local excision of the left breast without axillary lymph node management. No adjuvant chemotherapy or radiotherapy was prescribed. The detailed pathogenesis of PBO is not yet fully understood. Different origins and predisposing factors have been proposed. Complete removal of the mass with clear margins seems to be the most effective medical intervention. The significance of adjuvant chemotherapy and radiation therapy is still a matter of debate. Due to its rarity, PBO can be challenging to diagnose pre‑operatively, necessitating a detailed histological examination of the resected specimen along with immunohistochemistry to reach an accurate diagnosis.', 'Journal website', 'Paper', 'https://www.spandidos-publications.com/10.3892/wasj.2025.387', '2025-08-27', 'published', 'https://smarthealth.group/api/Images/Researches/e297aaae-c02c-405b-a71c-d49911ed745a-576x1080.jpg'),
  (1280, 'Thyroid Hemiagenesis: A Single-Center Case Series', 'Abdulwahid M. Salih, Hiwa O. Baba, Shaho F. Ahmed, Karzan M. Salih, Abdullah A. Qadir, Ayman M. Mustafa, Shko H. Hassan, Harun A. Ahmed, Aras J. Qaradakhy, Rebaz O. Mohammed, Aso N. Qadir, Ahmed H. Ahmed, Dindar H. Hama, Rawand R. Rafiq', 'Introduction : Thyroid hemiagenesis (TH) is a rare congenital anomaly characterized by the complete absence of one thyroid lobe, with or without absence of the isthmus. Its etiology remains unclear, and epidemiological data are limited. Although TH is often asymptomatic and discovered incidentally, it may pose clinical challenges when accompanied by thyroid dysfunction or structural abnormalities. This study reviews a single-center experience in diagnosing this condition and highlights its clinical significance.. Methods : This single-center case series was conducted from July 2021–July 2024, analyzing TH cases confirmed via ultrasonography. Eligible patients had complete medical records, including demographics, clinical presentation, radiological findings, and thyroid function status. Data were retrieved from electronic records and analyzed using SPSS 27.0, employing descriptive statistics to summarize means, ranges, frequencies, and percentages, ensuring a comprehensive assessment of TH’s clinical and epidemiological characteristics.. Results : This study analyzed 11 patients with TH (mean age: 28.12 ± 18.14 years; range: <1–55 years), seven of whom were females (63.6%). The diagnosis was incidental in six cases (54.5%), while three (27.3%) presented with neck swelling and two (18.2%) with neck pain. Thyroid function was euthyroid in seven (63.6%), hyperthyroid in two (18.2%), and hypothyroid in two (18.2%). Ultrasound examination confirmed left lobe and isthmus agenesis in eight cases (72.7%). Follow-up ranged from 4 to 48 months. Conclusion : This study confirms the female predominance of TH, with left-lobe absence being the most common. Congenital anomalies suggest embryological links. While thyroid function is typically preserved, those with hypo- and hyperthyroidism highlight the need for individualized endocrine assessment and monitoring.', 'Journal website', 'Paper', 'https://www.judijournal.com/index.php/jd/article/view/13', '2025-06-10', 'published', 'https://smarthealth.group/api/Images/Researches/80d5dbe6-c3a8-4ba7-b2d7-79af055d4e21-631x1080.jpg'),
  (1272, 'Pleomorphic adenoma of the lip: a case report and literature review', 'Rawa M Ali, Rebaz M Ali, Aras J Qaradakhy , Dilan S Hiwa, Ari M Abdullah, Diyar A Omar, Shko H Hassan, Abdullah A Qadir, Abdulwahid M Salih, Fahmi H Kakamad', 'Pleomorphic adenoma (PA) most commonly affects the major salivary glands but can also involve the minor salivary glands, particularly those of the hard and soft palate. However, the current study aims to present a case of upper lip PA. A 29-year-old male presented with a painless, firm, slow-growing swelling (1.5 × 1.5 cm) on the left upper lip. Ultrasonography showed a solid, hypoechoic nodule with irregular margins and mild peripheral vascularity. The encapsulated tumor was excised, and histopathology confirmed PA. At the 7-month follow-up, no evidence of recurrence was observed. Though typically seen in adults aged 40–70, PA can affect younger patients. Complete excision with clear margins is essential due to the risk of recurrence or malignant transformation. PA should be considered in the differential diagnosis of upper lip swellings.', 'Journal of Surgical Case Reports', 'Paper', 'https://academic.oup.com/jscr/article/2025/5/rjaf311/8131759', '2025-05-15', 'published', 'https://smarthealth.group/api/Images/Researches/725239c9-8994-4632-af29-8533fa255954-632x1080.png'),
  (1271, 'Papillary and medullary thyroid carcinoma with a single hybrid lymph node: a case report with review of literature', 'Ari M Abdullah, Shaho F Ahmed, Rawa M Ali, Aras J Qaradakhy, Abdulwahid M Salih, Aso S Muhialdeen, Hardi M Dhahir, Abdullah A Qadir, Shko H Hassan, Fahmi H Kakamad', 'Synchronous medullary and papillary thyroid carcinoma (MTC-PTC) is rare, particularly with metastasis to the same lymph node. This study presents a unique case of synchronous metastatic MTC and PTC in a single lymph node. A 35-year-old male presented with a neck swelling, diagnosed with MTC-PTC. Imaging revealed thyroid nodules, and histopathological examination following thyroidectomy confirmed mixed MTC-PTC with lymph node metastasis. Literature reports similar cases in patients aged 24–64, often presenting with neck lumps. Management typically involves total thyroidectomy with lymph node dissection, yielding favorable outcomes. Treatment should follow guidelines based on disease stage. Due to its rarity, further research is needed to better understand and manage this condition.', 'Journal of Surgical Case Reports', 'Paper', 'https://academic.oup.com/jscr/article/2025/6/rjaf389/8163643', '2025-06-16', 'published', 'https://smarthealth.group/api/Images/Researches/2be998fd-af04-4027-b3fc-52a5b9728bd5-588x1080.png'),
  (1268, 'Thyroid Hemi-agenesis: A Single-Center Case Series', 'Abdulwahid M. Salih, Hiwa O. Baba, Shaho F. Ahmed, Karzan M. Salih, Abdullah A. Qadir, Ayman M. Mustafa, Shko H. Hassan, Harun A. Ahmed, Aras J. Qaradakhy, Rebaz O. Mohammed, Aso N. Qadir, Ahmed H. Ahmed, Dindar H. Hama, Rawand R. Rafiq', 'Introduction : Thyroid hemiagenesis (TH) is a rare congenital anomaly characterized by the complete absence of one thyroid lobe, with or without absence of the isthmus. Its etiology remains unclear, and epidemiological data are limited. Although TH is often asymptomatic and discovered incidentally, it may pose clinical challenges when accompanied by thyroid dysfunction or structural abnormalities. This study reviews a single-center experience in diagnosing this condition and highlights its clinical significance.. Methods : This single-center case series was conducted from July 2021–July 2024, analyzing TH cases confirmed via ultrasonography. Eligible patients had complete medical records, including demographics, clinical presentation, radiological findings, and thyroid function status. Data were retrieved from electronic records and analyzed using SPSS 27.0, employing descriptive statistics to summarize means, ranges, frequencies, and percentages, ensuring a comprehensive assessment of TH’s clinical and epidemiological characteristics.. Results : This study analyzed 11 patients with TH (mean age: 28.12 ± 18.14 years; range: <1–55 years), seven of whom were females (63.6%). The diagnosis was incidental in six cases (54.5%), while three (27.3%) presented with neck swelling and two (18.2%) with neck pain. Thyroid function was euthyroid in seven (63.6%), hyperthyroid in two (18.2%), and hypothyroid in two (18.2%). Ultrasound examination confirmed left lobe and isthmus agenesis in eight cases (72.7%). Follow-up ranged from 4 to 48 months. Conclusion : This study confirms the female predominance of TH, with left-lobe absence being the most common. Congenital anomalies suggest embryological links. While thyroid function is typically preserved, those with hypo- and hyperthyroidism highlight the need for individualized endocrine assessment and monitoring.', 'Journal website', 'Paper', 'https://www.judijournal.com/index.php/jd/article/view/13', '2025-06-10', 'published', 'https://smarthealth.group/api/Images/Researches/b4c3675f-0213-4dba-aa57-4ff799982b78-603x1080.png'),
  (1265, 'Simultaneous quadruple pathology in the thyroid gland: A case report with literature review', 'Ari M. Abdullah, Rawa M. Ali, Abdulwahid M. Salih, Aras J. Qaradakhy, Hardi M. Dhahir, Aso S. Muhialdeen, Shko H. Hassan, Shaho F. Ahmed, Imad J. Habibullah, Fahmi H. Kakamand', 'It is unusual for 2 distinct thyroid tumors to coexist, and even rarer to observe more than 2 thyroid pathologies alongside a malignant lymph node process. This report describes a highly rare presentation of multiple thyroid diseases coexisting with an extra-thyroidal malignancy. A 32-year-old female presented with suspicious thyroid nodules and bilateral pathological lymphadenopathy on ultrasound. Fine-needle aspiration (FNA) suggested both papillary thyroid carcinoma (PTC) and Hodgkin lymphoma (HL). Histopathology confirmed multifocal papillary thyroid microcarcinomas (PTMC), hyalinizing trabecular tumor (HTT), Hashimoto’s thyroiditis (HT), and HL in a cervical lymph node. Managing such cases is clinically challenging due to their rarity and variable presentations. Further research is needed to guide evaluation and treatment strategies.', 'Journal website', 'Paper', 'https://www.sciencedirect.com/science/article/pii/S1930043325004170', '2025-05-27', 'published', 'https://smarthealth.group/api/Images/Researches/4fa2f3ea-c480-4165-ab57-b4c7752098d1-590x1080.png'),
  (1264, 'Unilateral breast Darier disease: A case report and literature review', 'Lana R.A. Pshtiwan, Shaban Latif Tofiq, Dilan S. Hiwa, Harzal Hiwa Fatih, Karukh K. Mohammed, Abdulwahid M. Salih, Diyar A. Omar, Kayhan A. Najar, Fahmi H. Kakamad', 'Darier disease is often an underrecognized, disfiguring skin condition. Although the localized form of this condition has been reported in several parts of the body, the present study describes the case of a patient with the unique involvement of one breast, destroying the nipple. A 35‑year‑old female patient complained of having a right nipple lesion for 1 month. There were multiple small brown‑to‑black firm nipple lesions causing nipple destruction, associated with multiple small red, non‑tender skin lesions in the areolar region and lower part of the breast. An incisional biopsy revealed a small number of acantholytic cells and a papillary‑like configuration within the epidermis; no conclusive evidence of malignancy was observed, and a diagnosis of Darier disease was made. Emollient lotion, topical fusidic acid cream 2%, and oral isotretinoin 20 mg once daily were prescribed. The proposed pathogenesis of localized Darier disease is due to genetic mosaicism; these mutations arise during zygotic division. It can present as a rash with either macular or linear patterns confined to a specific body area. In the literature review, localized Darier disease affecting the inframammary region, vulva, axilla, and side of the abdomen have been reported, among others. Paget''s disease was hidden in the background of Darier''s disease of the breast in one of the cases in the literature. Darier disease may present as a localized unilateral breast lesion, characterized by multiple small, firm brown to black lesions on the nipple, leading to nipple destruction.', 'Journal website', 'Paper', 'https://www.spandidos-publications.com/10.3892/mi.2025.244', '2025-05-26', 'published', 'https://smarthealth.group/api/Images/Researches/b9c3cea2-510e-480a-9743-a34d065f54df-591x1080.png'),
  (1263, 'Hyalinizing Trabecular Tumor: A Case Series with Literature Review', 'Abdulwahid M. Salih, Rebaz O. Mohammed, Hiwa O. Baba, Shko H. Hassan, Muhammed Bag A. Ali, Imad J. Habibullah, Imad S. Sedeeq, Dyari Q. Hamad, Karokh K. Mohammed, Marwan N. Hassan, Abdullah A. Qadir, Harun A. Ahmed, Meer M. Abdulkareem, Fahmi H. Kakamad', 'Introduction: Hyalinizing trabecular tumor (HTT) is a rare thyroid neoplasm originating from follicular cells and poses diagnostic challenges due to its cytologic and histologic overlap with other thyroid malignancies. This study aims to present the clinical features and management of HTT cases treated at a single center. Methods: This was a single-center retrospective case series. The patients were included from January 2019 to November 2024. Data collection took place over one month, from November 15, 2024, to December 15, 2024. The study included patients with HTT whose diagnoses were confirmed histopathologically. Results: The case series included 11 patients, predominantly female, 10 (90.9%), with a mean age of 50.7±19.01 years. The most common presenting symptom was anterior neck swelling, recorded in 5 (45.5%), while one case (9.1%) was discovered incidentally. Hyperthyroidism was present in 6 (54.5%). The tumors were distributed within the thyroid gland as follows: left lobe in 5 (45.5%) cases, right lobe in 4 (36.4%) cases, and isthmus in 2 (18.1%) cases. Total thyroidectomy was performed in 7 patients (63.6%), with tumor sizes ranging from 0.5 to 5.5 cm and a mean diameter of 2.6 ± 2.05 cm. All diagnoses were confirmed postoperatively through histopathological examination. Conclusion: A rare benign tumor, HTT remains challenging to diagnose accurately. Both total thyroidectomy and lobectomy may result in good outcomes.', 'Journal website', 'Paper', 'https://www.judijournal.com/index.php/jd/article/view/10', '2025-05-24', 'published', 'https://smarthealth.group/api/Images/Researches/4dba663e-8a7b-4d0c-8503-93978d6cb365-588x1080.png')
